-- 网关存储库在 PostgreSQL 上的起点,等价于 MySQL 迁移 0001-0064 跑完后的表结构。
--
-- 由 internal/bootstrap/pgschema_test.go 的 TestGenPGBaseline 从真实 MySQL 生成,**不要手改**;
-- 之后的表结构变化写成新的迁移(MySQL 的 migrations/00xx_*.sql 与这里的 pg/00xx_*.sql
-- 各一份、编号相同),TestPGSchemaMatchesMySQL 会把两边逐列比对。
--
-- 字符串列一律 citext(与 MySQL 的 *_ci 一致:不分大小写的比较、LIKE、唯一索引),
-- 长度上限由 CHECK 约束补回。需要 PostgreSQL 13+(citext 为受信扩展,库属主即可创建)。

CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE "tbl_api_client" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" citext NOT NULL CHECK (char_length("name") <= 64),
  "key" citext NOT NULL CHECK (char_length("key") <= 64),
  "secret_hash" citext NOT NULL CHECK (char_length("secret_hash") <= 255),
  "user_id" bigint NOT NULL,
  "user_name" citext CHECK (char_length("user_name") <= 64),
  "allow_ips" citext CHECK (char_length("allow_ips") <= 512),
  "scopes" citext NOT NULL CHECK (char_length("scopes") <= 255),
  "enabled" boolean NOT NULL DEFAULT true,
  "last_used_at" timestamptz(3),
  "created_by" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz(3),
  "pipeline_id" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "tbl_api_client__idx_apiclient_key" ON "tbl_api_client" ("key");

CREATE TABLE "tbl_approval" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "ap_no" citext NOT NULL CHECK (char_length("ap_no") <= 32),
  "connection_id" bigint NOT NULL,
  "env" citext NOT NULL CHECK (char_length("env") <= 32),
  "instance" citext NOT NULL CHECK (char_length("instance") <= 64),
  "command" citext NOT NULL CHECK (octet_length("command") <= 16777215),
  "keyword" citext CHECK (char_length("keyword") <= 32),
  "db_name" citext CHECK (char_length("db_name") <= 128),
  "initiator_id" bigint NOT NULL,
  "initiator" citext CHECK (char_length("initiator") <= 64),
  "reason" citext CHECK (char_length("reason") <= 512),
  "risk_level" citext NOT NULL CHECK (char_length("risk_level") <= 16),
  "status" citext NOT NULL DEFAULT 'pending' CHECK (char_length("status") <= 16),
  "audit_id" citext CHECK (char_length("audit_id") <= 32),
  "result" citext CHECK (octet_length("result") <= 65535),
  "result_rows" integer,
  "escalated" boolean NOT NULL DEFAULT false,
  "decided_at" timestamptz(3),
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "external_task_id" citext NOT NULL DEFAULT '' CHECK (char_length("external_task_id") <= 128),
  "tier_code" citext NOT NULL DEFAULT '' CHECK (char_length("tier_code") <= 16),
  "script_upload_id" bigint NOT NULL DEFAULT 0,
  "script_sha256" citext NOT NULL DEFAULT '' CHECK (char_length("script_sha256") <= 64),
  "release_id" bigint NOT NULL DEFAULT 0,
  "executed_at" timestamptz(3),
  "export_job_id" bigint NOT NULL DEFAULT 0,
  "exec_status" citext CHECK (char_length("exec_status") <= 16),
  "window_id" bigint NOT NULL DEFAULT 0,
  "command_ref" citext CHECK (octet_length("command_ref") <= 65535),
  "osc_job_id" bigint NOT NULL DEFAULT 0,
  "notice" citext CHECK (octet_length("notice") <= 65535),
  "notice_ref" citext CHECK (octet_length("notice_ref") <= 65535),
  "result_ref" citext CHECK (octet_length("result_ref") <= 65535),
  "external_dispatched" boolean NOT NULL DEFAULT false,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "tbl_approval__idx_approval_apno" ON "tbl_approval" ("ap_no");
CREATE INDEX "tbl_approval__idx_approval_export" ON "tbl_approval" ("export_job_id");
CREATE INDEX "tbl_approval__idx_approval_ext" ON "tbl_approval" ("external_task_id");
CREATE INDEX "tbl_approval__idx_approval_initiator" ON "tbl_approval" ("initiator_id");
CREATE INDEX "tbl_approval__idx_approval_release" ON "tbl_approval" ("release_id");
CREATE INDEX "tbl_approval__idx_approval_status" ON "tbl_approval" ("status");
CREATE INDEX "tbl_approval__idx_approval_window" ON "tbl_approval" ("window_id");

CREATE TABLE "tbl_approval_step" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "approval_id" bigint NOT NULL,
  "step_order" integer NOT NULL,
  "approver_id" bigint NOT NULL,
  "approver" citext CHECK (char_length("approver") <= 64),
  "status" citext NOT NULL DEFAULT 'waiting' CHECK (char_length("status") <= 16),
  "acted_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_approval_step__idx_approval_step_approver" ON "tbl_approval_step" ("approver_id");
CREATE INDEX "tbl_approval_step__idx_step_approval" ON "tbl_approval_step" ("approval_id");

CREATE TABLE "tbl_async_job" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "connection_id" bigint NOT NULL,
  "instance" citext NOT NULL DEFAULT '' CHECK (char_length("instance") <= 96),
  "db_name" citext NOT NULL DEFAULT '' CHECK (char_length("db_name") <= 128),
  "sql" citext CHECK (octet_length("sql") <= 16777215),
  "reason" citext NOT NULL DEFAULT '' CHECK (char_length("reason") <= 512),
  "status" citext NOT NULL DEFAULT 'pending' CHECK (char_length("status") <= 16),
  "log" citext CHECK (octet_length("log") <= 16777215),
  "rows" integer NOT NULL DEFAULT 0,
  "error" citext NOT NULL DEFAULT '' CHECK (char_length("error") <= 512),
  "created_at" timestamptz(0),
  "started_at" timestamptz(0),
  "finished_at" timestamptz(0),
  "risk" citext NOT NULL DEFAULT '' CHECK (char_length("risk") <= 16),
  "error_ref" citext CHECK (octet_length("error_ref") <= 65535),
  "log_refs" citext CHECK (octet_length("log_refs") <= 16777215),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_async_job__idx_async_user" ON "tbl_async_job" ("user_id");

CREATE TABLE "tbl_audit_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "occurred_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "actor_id" bigint NOT NULL,
  "actor_name" citext CHECK (char_length("actor_name") <= 64),
  "connection_id" bigint,
  "instance" citext CHECK (char_length("instance") <= 64),
  "db_name" citext CHECK (char_length("db_name") <= 128),
  "command" citext NOT NULL CHECK (octet_length("command") <= 16777215),
  "risk" citext NOT NULL CHECK (char_length("risk") <= 16),
  "result" citext NOT NULL CHECK (char_length("result") <= 16),
  "approval_no" citext CHECK (char_length("approval_no") <= 32),
  "prev_hash" citext CHECK (char_length("prev_hash") <= 64),
  "hash" citext NOT NULL CHECK (char_length("hash") <= 64),
  "operator" citext NOT NULL DEFAULT '' CHECK (char_length("operator") <= 128),
  "env" citext NOT NULL DEFAULT '' CHECK (char_length("env") <= 32),
  "tier_code" citext NOT NULL DEFAULT '' CHECK (char_length("tier_code") <= 16),
  "event_type" citext NOT NULL DEFAULT '' CHECK (char_length("event_type") <= 16),
  "data_action" citext NOT NULL DEFAULT '' CHECK (char_length("data_action") <= 16),
  "client_ip" citext NOT NULL DEFAULT '' CHECK (char_length("client_ip") <= 45),
  "entry_source" citext NOT NULL DEFAULT '' CHECK (char_length("entry_source") <= 16),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_audit_log__idx_audit_action" ON "tbl_audit_log" ("data_action", "occurred_at");
CREATE INDEX "tbl_audit_log__idx_audit_actor" ON "tbl_audit_log" ("actor_id");
CREATE INDEX "tbl_audit_log__idx_audit_approval" ON "tbl_audit_log" ("approval_no");
CREATE INDEX "tbl_audit_log__idx_audit_event" ON "tbl_audit_log" ("event_type", "occurred_at");
CREATE INDEX "tbl_audit_log__idx_audit_risk" ON "tbl_audit_log" ("risk");
CREATE INDEX "tbl_audit_log__idx_audit_source" ON "tbl_audit_log" ("entry_source", "occurred_at");
CREATE INDEX "tbl_audit_log__idx_audit_time" ON "tbl_audit_log" ("occurred_at");
CREATE UNIQUE INDEX "tbl_audit_log__uk_audit_prev" ON "tbl_audit_log" ("prev_hash");

CREATE TABLE "tbl_connection" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" citext NOT NULL CHECK (char_length("name") <= 64),
  "engine" citext NOT NULL CHECK (char_length("engine") <= 32),
  "host" citext NOT NULL CHECK (char_length("host") <= 128),
  "port" integer NOT NULL,
  "env" citext NOT NULL CHECK (char_length("env") <= 32),
  "policy" citext NOT NULL CHECK (char_length("policy") <= 32),
  "default_role" citext CHECK (char_length("default_role") <= 64),
  "layer" citext CHECK (char_length("layer") <= 64),
  "username" citext CHECK (char_length("username") <= 64),
  "password" citext CHECK (char_length("password") <= 255),
  "db_name" citext CHECK (char_length("db_name") <= 128),
  "tags" citext CHECK (char_length("tags") <= 255),
  "status" citext NOT NULL DEFAULT 'online' CHECK (char_length("status") <= 16),
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "last_check_at" timestamptz(3),
  "last_check_ok" boolean,
  "last_check_err" citext NOT NULL DEFAULT '' CHECK (char_length("last_check_err") <= 512),
  "last_check_kind" citext NOT NULL DEFAULT '' CHECK (char_length("last_check_kind") <= 16),
  "biz_query" boolean NOT NULL DEFAULT false,
  "replica_host" citext NOT NULL DEFAULT '' CHECK (char_length("replica_host") <= 128),
  "replica_port" integer NOT NULL DEFAULT 0,
  "replica_username" citext NOT NULL DEFAULT '' CHECK (char_length("replica_username") <= 64),
  "replica_password" citext NOT NULL DEFAULT '' CHECK (char_length("replica_password") <= 255),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_connection__idx_connection_env" ON "tbl_connection" ("env");
CREATE UNIQUE INDEX "tbl_connection__idx_connection_name" ON "tbl_connection" ("name");

CREATE TABLE "tbl_database_project" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "connection_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "project_id" bigint NOT NULL,
  "created_by" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz(3),
  "updated_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_database_project__idx_db_project_project" ON "tbl_database_project" ("project_id");
CREATE UNIQUE INDEX "tbl_database_project__uk_db_project" ON "tbl_database_project" ("connection_id", "db_name");

CREATE TABLE "tbl_env_tier" (
  "code" citext NOT NULL CHECK (char_length("code") <= 16),
  "display_name" citext NOT NULL CHECK (char_length("display_name") <= 64),
  "sort_order" integer NOT NULL DEFAULT 0,
  "require_mfa" boolean NOT NULL DEFAULT false,
  "danger_banner" boolean NOT NULL DEFAULT false,
  "counts_in_pending" boolean NOT NULL DEFAULT false,
  "scan_baseline" boolean NOT NULL DEFAULT false,
  "conn_layer" citext NOT NULL DEFAULT '' CHECK (char_length("conn_layer") <= 64),
  "default_role" citext NOT NULL DEFAULT '' CHECK (char_length("default_role") <= 64),
  "strict_nowhere" boolean NOT NULL DEFAULT true,
  "mask_sensitive" boolean NOT NULL DEFAULT true,
  "biz_export_restrict" boolean NOT NULL DEFAULT true,
  "auto_execute" boolean NOT NULL DEFAULT false,
  PRIMARY KEY ("code")
);

CREATE TABLE "tbl_environment" (
  "code" citext NOT NULL CHECK (char_length("code") <= 32),
  "display_name" citext NOT NULL CHECK (char_length("display_name") <= 64),
  "tier_code" citext NOT NULL CHECK (char_length("tier_code") <= 16),
  "sort_order" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("code")
);
CREATE INDEX "tbl_environment__idx_environment_tier" ON "tbl_environment" ("tier_code");

CREATE TABLE "tbl_exec_window" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" citext NOT NULL CHECK (char_length("name") <= 64),
  "enabled" boolean NOT NULL DEFAULT true,
  "connection_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "kind" citext NOT NULL CHECK (char_length("kind") <= 16),
  "timezone" citext NOT NULL CHECK (char_length("timezone") <= 64),
  "starts_at" timestamptz(3),
  "ends_at" timestamptz(3),
  "weekdays" citext CHECK (char_length("weekdays") <= 32),
  "start_min" integer NOT NULL DEFAULT 0,
  "end_min" integer NOT NULL DEFAULT 0,
  "not_after" timestamptz(3),
  "reason" citext CHECK (char_length("reason") <= 255),
  "created_by" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz(3),
  "updated_at" timestamptz(3),
  "status" citext NOT NULL DEFAULT 'pending' CHECK (char_length("status") <= 16),
  "approval_id" bigint NOT NULL DEFAULT 0,
  "ap_no" citext CHECK (char_length("ap_no") <= 32),
  "decided_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_exec_window__idx_window_scope" ON "tbl_exec_window" ("connection_id", "db_name");

CREATE TABLE "tbl_exec_window_db" (
  "window_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  PRIMARY KEY ("window_id", "db_name")
);
CREATE INDEX "tbl_exec_window_db__idx_window_db_name" ON "tbl_exec_window_db" ("db_name");

CREATE TABLE "tbl_export_job" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "connection_id" bigint,
  "instance" citext CHECK (char_length("instance") <= 96),
  "db_name" citext CHECK (char_length("db_name") <= 128),
  "sql" citext CHECK (octet_length("sql") <= 16777215),
  "name" citext CHECK (char_length("name") <= 128),
  "status" citext NOT NULL DEFAULT 'pending' CHECK (char_length("status") <= 16),
  "rows" integer,
  "bytes" bigint,
  "parts" integer,
  "files" citext CHECK (octet_length("files") <= 65535),
  "password" citext CHECK (char_length("password") <= 128),
  "error" citext CHECK (char_length("error") <= 255),
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "finished_at" timestamptz(3),
  "include_sensitive" boolean NOT NULL DEFAULT false,
  "approval_id" bigint NOT NULL DEFAULT 0,
  "ap_no" citext CHECK (char_length("ap_no") <= 32),
  "export_format" citext NOT NULL DEFAULT 'csv' CHECK (char_length("export_format") <= 8),
  "target_table" citext CHECK (char_length("target_table") <= 128),
  "downloaded_at" timestamptz(3),
  "downloaded_files" citext CHECK (octet_length("downloaded_files") <= 16777215),
  "error_ref" citext CHECK (octet_length("error_ref") <= 65535),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_export_job__idx_export_approval" ON "tbl_export_job" ("approval_id");
CREATE INDEX "tbl_export_job__idx_export_user" ON "tbl_export_job" ("user_id");

CREATE TABLE "tbl_inspection_report" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "connection_id" bigint NOT NULL,
  "instance_name" citext NOT NULL CHECK (char_length("instance_name") <= 64),
  "report_date" citext NOT NULL CHECK (char_length("report_date") <= 10),
  "inspected_at" timestamptz(3),
  "score" integer,
  "level" citext NOT NULL CHECK (char_length("level") <= 16),
  "critical_count" integer NOT NULL DEFAULT 0,
  "warning_count" integer NOT NULL DEFAULT 0,
  "info_count" integer NOT NULL DEFAULT 0,
  "findings" citext CHECK (octet_length("findings") <= 16777215),
  "file_path" citext NOT NULL CHECK (char_length("file_path") <= 512),
  "size_bytes" bigint NOT NULL DEFAULT 0,
  "sha256" citext NOT NULL CHECK (char_length("sha256") <= 64),
  "api_client_id" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz(3),
  "updated_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_inspection_report__idx_inspection_date" ON "tbl_inspection_report" ("report_date");
CREATE INDEX "tbl_inspection_report__idx_inspection_level" ON "tbl_inspection_report" ("level");
CREATE UNIQUE INDEX "tbl_inspection_report__uk_inspection_report" ON "tbl_inspection_report" ("connection_id", "report_date");

CREATE TABLE "tbl_meta_column" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "connection_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "schema_name" citext NOT NULL DEFAULT '' CHECK (char_length("schema_name") <= 128),
  "table_name" citext NOT NULL CHECK (char_length("table_name") <= 128),
  "ordinal" integer NOT NULL DEFAULT 0,
  "column_name" citext NOT NULL CHECK (char_length("column_name") <= 128),
  "data_type" citext NOT NULL CHECK (char_length("data_type") <= 128),
  "nullable" boolean NOT NULL DEFAULT true,
  "col_default" citext NOT NULL DEFAULT '' CHECK (char_length("col_default") <= 512),
  "comment" citext NOT NULL DEFAULT '' CHECK (char_length("comment") <= 512),
  "is_pk" boolean NOT NULL DEFAULT false,
  "synced_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_meta_column__idx_meta_col_name" ON "tbl_meta_column" ("column_name");
CREATE INDEX "tbl_meta_column__idx_meta_col_scope" ON "tbl_meta_column" ("connection_id", "db_name", "table_name");
CREATE UNIQUE INDEX "tbl_meta_column__idx_meta_col_uniq" ON "tbl_meta_column" ("connection_id", "db_name", "schema_name", "table_name", "column_name");

CREATE TABLE "tbl_meta_sync" (
  "connection_id" bigint NOT NULL,
  "started_at" timestamptz(3),
  "finished_at" timestamptz(3),
  "db_count" integer NOT NULL DEFAULT 0,
  "table_count" integer NOT NULL DEFAULT 0,
  "column_count" integer NOT NULL DEFAULT 0,
  "err" citext NOT NULL DEFAULT '' CHECK (char_length("err") <= 512),
  PRIMARY KEY ("connection_id")
);

CREATE TABLE "tbl_meta_table" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "connection_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "schema_name" citext NOT NULL DEFAULT '' CHECK (char_length("schema_name") <= 128),
  "table_name" citext NOT NULL CHECK (char_length("table_name") <= 128),
  "kind" citext NOT NULL DEFAULT 'table' CHECK (char_length("kind") <= 16),
  "comment" citext NOT NULL DEFAULT '' CHECK (char_length("comment") <= 512),
  "synced_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_meta_table__idx_meta_table_name" ON "tbl_meta_table" ("table_name");
CREATE UNIQUE INDEX "tbl_meta_table__idx_meta_table_uniq" ON "tbl_meta_table" ("connection_id", "db_name", "schema_name", "table_name");

CREATE TABLE "tbl_notification" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "type" citext NOT NULL CHECK (char_length("type") <= 32),
  "title" citext NOT NULL CHECK (char_length("title") <= 128),
  "body" citext CHECK (char_length("body") <= 512),
  "ref_no" citext CHECK (char_length("ref_no") <= 32),
  "is_read" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "body_ref" citext CHECK (octet_length("body_ref") <= 65535),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_notification__idx_notif_user" ON "tbl_notification" ("user_id");

CREATE TABLE "tbl_osc_job" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "connection_id" bigint NOT NULL,
  "instance" citext NOT NULL CHECK (char_length("instance") <= 64),
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "tbl_name" citext NOT NULL CHECK (char_length("tbl_name") <= 64),
  "statement" citext NOT NULL CHECK (octet_length("statement") <= 65535),
  "change_json" citext NOT NULL CHECK (octet_length("change_json") <= 65535),
  "approval_id" bigint NOT NULL DEFAULT 0,
  "ap_no" citext CHECK (char_length("ap_no") <= 32),
  "release_id" bigint NOT NULL DEFAULT 0,
  "initiator_id" bigint NOT NULL,
  "initiator" citext CHECK (char_length("initiator") <= 64),
  "size_rows" bigint NOT NULL DEFAULT 0,
  "size_bytes" bigint NOT NULL DEFAULT 0,
  "warnings" citext CHECK (octet_length("warnings") <= 65535),
  "status" citext NOT NULL CHECK (char_length("status") <= 16),
  "phase" citext CHECK (char_length("phase") <= 16),
  "rows_estimated" bigint NOT NULL DEFAULT 0,
  "rows_copied" bigint NOT NULL DEFAULT 0,
  "chunks" integer NOT NULL DEFAULT 0,
  "rows_replayed" bigint NOT NULL DEFAULT 0,
  "cut_over_attempts" integer NOT NULL DEFAULT 0,
  "throttled" boolean NOT NULL DEFAULT false,
  "paused" boolean NOT NULL DEFAULT false,
  "error" citext CHECK (octet_length("error") <= 65535),
  "old_table" citext CHECK (char_length("old_table") <= 64),
  "created_at" timestamptz(3),
  "started_at" timestamptz(3),
  "finished_at" timestamptz(3),
  "updated_at" timestamptz(3),
  "throttle_reason" citext NOT NULL DEFAULT '' CHECK (char_length("throttle_reason") <= 255),
  "checkpoint" citext CHECK (octet_length("checkpoint") <= 65535),
  "error_ref" citext CHECK (octet_length("error_ref") <= 65535),
  "throttle_reason_ref" citext CHECK (octet_length("throttle_reason_ref") <= 65535),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_osc_job__idx_osc_job_approval" ON "tbl_osc_job" ("approval_id");
CREATE INDEX "tbl_osc_job__idx_osc_job_conn" ON "tbl_osc_job" ("connection_id");
CREATE INDEX "tbl_osc_job__idx_osc_job_status" ON "tbl_osc_job" ("status");

CREATE TABLE "tbl_pipeline" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" citext NOT NULL CHECK (char_length("name") <= 128),
  "description" citext CHECK (char_length("description") <= 512),
  "tier_code" citext CHECK (char_length("tier_code") <= 16),
