CREATE INDEX "tbl_pipeline_stage__idx_pstage_pipeline" ON "tbl_pipeline_stage" ("pipeline_id");

CREATE TABLE "tbl_project" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" citext NOT NULL CHECK (char_length("name") <= 64),
  "owner" citext CHECK (char_length("owner") <= 64),
  "description" citext CHECK (char_length("description") <= 512),
