CREATE UNIQUE INDEX "tbl_project__uk_project_name" ON "tbl_project" ("name");

CREATE TABLE "tbl_query_grant" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "connection_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "max_rows" integer NOT NULL DEFAULT 0,
  "timeout_sec" integer NOT NULL DEFAULT 0,
  "allow_export" boolean NOT NULL DEFAULT false,
  "starts_at" timestamptz(3) NOT NULL,
  "ends_at" timestamptz(3) NOT NULL,
  "status" citext NOT NULL DEFAULT 'active' CHECK (char_length("status") <= 16),
  "client_id" bigint NOT NULL DEFAULT 0,
  "client_name" citext NOT NULL DEFAULT '' CHECK (char_length("client_name") <= 64),
  "external_id" citext NOT NULL DEFAULT '' CHECK (char_length("external_id") <= 128),
  "approver" citext NOT NULL DEFAULT '' CHECK (char_length("approver") <= 128),
  "reason" citext NOT NULL DEFAULT '' CHECK (char_length("reason") <= 512),
  "revoked_at" timestamptz(3),
  "revoked_by" citext NOT NULL DEFAULT '' CHECK (char_length("revoked_by") <= 128),
  "created_at" timestamptz(3),
  "updated_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE INDEX "tbl_query_grant__idx_query_grant_ends" ON "tbl_query_grant" ("ends_at");
CREATE INDEX "tbl_query_grant__idx_query_grant_ext" ON "tbl_query_grant" ("external_id");
CREATE UNIQUE INDEX "tbl_query_grant__uk_query_grant" ON "tbl_query_grant" ("user_id", "connection_id", "db_name");

