  "status" citext NOT NULL DEFAULT 'pending' CHECK (char_length("status") <= 16),
  "risk" citext CHECK (char_length("risk") <= 16),
  "error" citext CHECK (char_length("error") <= 512),
  "created_at" timestamptz(3),
  "started_at" timestamptz(3),
  "finished_at" timestamptz(3),
  "source" citext NOT NULL DEFAULT 'console' CHECK (char_length("source") <= 16),
  "client_id" bigint NOT NULL DEFAULT 0,
